  (* LPS 727298f3: [RESF] now asks that its window be mapped ([AllocRepX.ak_resf_hi]).  On the
     slow path the free-array chunk [FAB + mfa, + 262144) is the next one, and it lies inside the
     primary region [PRIM] maps: the pending entries fit in the user map ([NFAU], [MU'], [AUR],
     at least 32 bytes each), so [mfa] stays a chunk below [kFreeArraySize].  [rf_mid_map]'s
     recorded proof passes this lemma there. *)
  Lemma rf_mid_mc : mfa < 4 * (nf + nnew) ->
    map_contains (vm_maps (m_vmmaps mo)) (Z_to_bv 64 (FAB + mfa)) (Z_to_bv 64 262144) = true.
  Proof.
    intros SLOW.
    assert (U : forall z, 0 <= z < 2 ^ 64 -> bv_unsigned (Z_to_bv 64 z) = z)
      by (intros z Hz; rewrite Z_to_bv_unsigned; apply bv_wrap_small; unfold bv_modulus; exact Hz).
    pose proof SBR as S1. pose proof AUR as A1. pose proof HC as H1. pose proof NFR as N1.
    pose proof MU' as M2. pose proof NFAU as N2.
    pose proof (class_size_table_facts c ltac:(clear - H1; lia)) as (_ & _ & CS & _).
    assert (CSZ : 32 <= csz) by (unfold csz; apply CS; clear - H1; lia).
    destruct A1 as ((A1a & A1b) & A1c). destruct M2 as (_ & (M2a & M2b) & _). destruct N1 as (N1a & N1b & N1c).
    assert (NN : 0 <= nnew) by (unfold nnew; apply Z.div_pos; lia).
    assert (D : csz * nnew <= mu' - au) by (unfold nnew; apply Z.mul_div_le; lia).
    assert (E : 32 * (nf + nnew) <= csz * (nf + nnew)) by (apply Z.mul_le_mono_nonneg_r; lia).
    assert (B : AHI_LO <= sb /\ sb + 2 ^ 37 + 4096 <= aceil /\ 1 <= c <= 30 /\ 0 <= mfa /\ mfa + 262144 <= 536870912)
      by (clear - S1 H1 A1a A1b A1c M2a M2b N1a N1b N2 D E SLOW; unfold kSpaceSize, kPageSize, kUserMapSize, kFreeArrayOffset in *; lia).
    clear - PRIM B U. pose proof aceil_facts as AF.
    apply PRIM; unfold FAB, rbeg, kFreeArrayOffset; rewrite !U; unfold AHI_LO in *; lia.
  Qed.

  (* [comment removed for export] *)
  Lemma rf_mid_map : forall msF1 mo1, mfa < 4 * (nf + nnew) ->
    rf3_at L S Zr mo ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m lo c CA P R sb ARI rbeg FAB TH TSD CTX nf mfa au mu mu' fl msF1 mo1 ->
    (forall msF' mo', rf4_at L S Zr mo ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m lo c CA P R sb ARI rbeg FAB TH TSD CTX nf mfa au mu mu' (mfa + 262144) fl msF' mo' ->
                      sreach asegs Q (mkCfg msF' mo')) ->
